      intakes: [{ method: "GET", path: "/v1/intakes" }, { method: "POST", path: "/v1/intakes" }, { method: "GET", path: "/v1/intakes/:intakeId" }, { method: "POST", path: "/v1/intakes/:intakeId/assign" }, { method: "POST", path: "/v1/intakes/:intakeId/convert" }, { method: "POST", path: "/v1/intakes/:intakeId/expire" }],
      overlaps: [{ method: "GET", path: "/v1/overlaps" }, { method: "POST", path: "/v1/overlaps" }, { method: "GET", path: "/v1/overlaps/:overlapId" }, { method: "POST", path: "/v1/overlaps/:overlapId/resolve" }],
      packs: [{ method: "GET", path: "/v1/packs" }, { method: "POST", path: "/v1/packs" }, { method: "GET", path: "/v1/packs/:packId" }, { method: "POST", path: "/v1/packs/:packId/publish" }],
